"""Summarize finalized door avoidance evidence without modifying any episode."""
import argparse,json,hashlib
from pathlib import Path
parser=argparse.ArgumentParser();parser.add_argument('--output',default='reports/avoidance_trials/doors/summary_v2.json');args=parser.parse_args()
root=Path(__file__).resolve().parents[3];entries=[]
for variant,attempt in [('human','human_attempt_02'),('property','property_attempt_04'),('robot','robot_attempt_02')]:
 ep=root/'datasets/avoidance_trials/doors'/attempt;aname='avoidance_audit.json';suffix='';fname='fixed_base_hazard_audit'+suffix+'.json';hname='hazard_clearance'+suffix+'.json';pname='path_comparison'+suffix+'.png';r=json.loads((ep/'result.json').read_text());a=json.loads((ep/aname).read_text());m=json.loads((ep/'metadata.json').read_text());v=json.loads((ep/'validation_full.json').read_text());self_audit=json.loads((ep/'self_collision_audit.json').read_text());fixed=json.loads((ep/fname).read_text());gate=all([r['accepted'],a['accepted'],v['accepted'],self_audit['passed'],fixed['passed'],(ep/pname).is_file()]);assert gate
 entries.append({'variant':variant,'episode':str(ep.relative_to(root)),'baseline':a['baseline_episode'],'selected_avoidance_report':aname,'accepted':gate,'frames':r['frames'],'physics_records':r['safety_checks'],'baseline_min_distance_m':a['baseline_counterfactual']['min_distance_m'],'actual_min_distance_m':a['augmented_actual']['min_distance_m'],'required_m':a['augmented_actual']['required_m'],'baseline_intersects':a['baseline_counterfactual']['minimum']['intersecting'],'source_layout_equal':a['same_source_layout'],'same_controller_policy':a['same_controller_policy'],'initial_and_goal_feasible':a['initial_and_goal_feasible'],'hazard_environment_legal':a['hazard_environment_legal'],'handle_offset_m':m.get('selected_handle_offset_z_m',.12),'final_door_rad':r['final_door_rad'],'property_stability':a['property_stability'],'path_comparison':a['path_comparison'],'comparison_camera':'external_camera_2','reports_sha256':{name:hashlib.sha256((ep/name).read_bytes()).hexdigest() for name in ['result.json','metadata.json','validation_full.json','audit.json','self_collision_audit.json',aname,fname,hname,pname]}})
out=root/args.output
if out.exists():raise FileExistsError(out)
out.write_text(json.dumps({'accepted':True,'accepted_variants':3,'original_task':'kitchen_bench_lightwheel_open_fridge','sampling':'Baseline actual obs/next_obs at15Hz; augmented measured physics every120Hz plus action postchecks. Unsafe baseline only evaluated offline.','scope':'One fixed layout and one successful episode per category; remaining7 door tasks and randomized/batch collection unverified. Old smoke samples are distinct.','entries':entries},indent=2)+'\n');print(json.dumps(entries,indent=2))
